.category-list {
  display: flex; gap: 1rem; flex-wrap: wrap;
}
.category-card {
  display: flex; flex-direction: column; align-items: center; gap: .6rem;
  text-decoration: none; color: var(--text);
  font-size: .8125rem; font-weight: 600;
  flex: 1 1 80px; min-width: 80px; max-width: 140px;
}
.category-card:hover { color: var(--accent); }
.category-thumb {
  width: 100%; aspect-ratio: 1;
  border-radius: var(--r-md);
  background: var(--surface-2);
  transition: transform .2s;
}
@media (prefers-reduced-motion: no-preference) {
  .category-card:hover .category-thumb { transform: translateY(-3px); }
}
/* Category colour fills */
.cat-clothing   { background: linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%); }
.cat-accessories{ background: linear-gradient(135deg, #fce7f3 0%, #fbcfe8 100%); }
.cat-home       { background: linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%); }
.cat-beauty     { background: linear-gradient(135deg, #fef9c3 0%, #fef08a 100%); }
.cat-tech       { background: linear-gradient(135deg, #ede9fe 0%, #ddd6fe 100%); }

