/* Badges */
.badge {
  position: absolute; top: .6rem; left: .6rem;
  font-size: .68rem; font-weight: 700; letter-spacing: .07em;
  text-transform: uppercase; padding: .2rem .55rem;
  border-radius: 999px; pointer-events: none;
}
.badge-new        { background: var(--text); color: #fff; }
.badge-bestseller { background: var(--green); color: #fff; }

/* Wishlist */
.wishlist-btn {
  position: absolute; top: .6rem; right: .6rem;
  width: 34px; height: 34px;
  background: rgba(255,255,255,.9); border: 1px solid var(--border);
  border-radius: 50%; display: flex; align-items: center;
  justify-content: center; cursor: pointer; color: var(--text-muted);
  transition: color .15s, background .15s;
}
.wishlist-btn:hover { color: var(--accent); background: #fff; }
.wishlist-btn[aria-pressed="true"] { color: var(--accent); }
.wishlist-btn[aria-pressed="true"] svg { fill: var(--accent); }

/* Product info */
.product-info {
  padding: 1rem; flex: 1;
  display: flex; flex-direction: column; gap: .35rem;
}
.product-brand {
  font-size: .72rem; font-weight: 600; letter-spacing: .08em;
  text-transform: uppercase; color: var(--text-muted);
}
.product-name { font-size: .9375rem; font-weight: 700; line-height: 1.3; }
.product-name a { text-decoration: none; color: var(--text); }
.product-name a:hover { text-decoration: underline; text-underline-offset: 2px; }
.product-rating {
  display: flex; align-items: center; gap: .3rem;
  font-size: .78rem; color: var(--text-muted);
}
.stars { color: #d97706; letter-spacing: 1px; font-size: .8rem; }
.rating-count { color: var(--text-muted); }
.product-pricing { margin-top: auto; padding-top: .5rem; }
.price { font-size: 1.1rem; font-weight: 800; }

/* ─── Deals section ──────────────────────────────────────────────── */
.deals-section { background: var(--surface); padding-block: 4rem; }
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto;
  gap: 1.25rem;
}
.deal-card {
  background: var(--bg); border: 1px solid var(--border);
  border-radius: var(--r-md); box-shadow: var(--shadow);
  overflow: hidden; display: flex; flex-direction: column;
}
.deal-card--wide { grid-row: span 2; }
.deal-image {
  width: 100%; background: var(--surface-2);
  background-size: cover; background-position: center;
}
.deal-card--wide .deal-image { aspect-ratio: 4/3; flex: 1; }
.deal-card:not(.deal-card--wide) .deal-image { aspect-ratio: 16/9; }

/* Deal image fills */
.di-1 { background: linear-gradient(160deg, #1e293b 0%, #334155 100%);
