.deal-content { padding: 1.25rem; display: flex; flex-direction: column; gap: .6rem; }
.deal-tag {
  display: inline-block; font-size: .68rem; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase;
  background: var(--accent-light); color: var(--accent);
  border: 1px solid rgba(234,88,12,.2); padding: .2rem .6rem;
  border-radius: 999px; width: fit-content;
}
.deal-content h3 { font-size: .9375rem; font-weight: 700; line-height: 1.3; }
.deal-card--wide .deal-content h3 { font-size: 1.25rem; }
.deal-desc { font-size: .875rem; color: var(--text-muted); }
.deal-pricing {
  display: flex; align-items: baseline; gap: .5rem;
  margin: .25rem 0;
}
.price-now { font-size: 1.15rem; font-weight: 800; }
.deal-card--wide .price-now { font-size: 1.5rem; }
.price-was { font-size: .85rem; color: var(--text-muted); text-decoration: line-through; }
.discount-badge {
  font-size: .72rem; font-weight: 700;
  background: #dcfce7; color: var(--green);
  border-radius: 999px; padding: .15rem .5rem;
}

/* ─── Trust bar ───────────────────────────────────────────────────── */
.trust-bar { padding-block: 2.5rem; border-top: 1px solid var(--border); }
.trust-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}
.trust-item {
  display: flex; align-items: flex-start; gap: .9rem;
}
.trust-item svg { flex-shrink: 0; color: var(--accent); margin-top: .1rem; }
.trust-item strong { display: block; font-size: .9rem; font-weight: 700; }
.trust-item p { font-size: .8125rem; color: var(--text-muted); }

/* ─── Editorial ───────────────────────────────────────────────────── */
.editorial-section { padding-block: 4rem; }
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
  align-items: start;
}
.editorial-card {
  background: var(--bg); border: 1px solid var(--border);
  border-radius: var(--r-md); overflow: hidden;
  box-shadow: var(--shadow);
}
.editorial-link { text-decoration: none; color: var(--text); display: block; }
.editorial-image {
  width: 100%; background-size: cover; background-position: center;
  background-color: var(--surface-2);
}
.editorial-card--hero .editorial-image { aspect-ratio: 4/3; }
.editorial-card:not(.editorial-card--hero) .editorial-image { aspect-ratio: 16/9; }

/* Editorial image fills */
