  .editorial-card:hover .editorial-image { transform: scale(1.03); }
}
.editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; }
.editorial-tag {
  font-size: .7rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: var(--accent);
}
.editorial-card h3 { font-size: .9375rem; font-weight: 700; line-height: 1.3; }
.editorial-card--hero h3 { font-size: 1.25rem; }
.editorial-card p { font-size: .85rem; color: var(--text-muted); line-height: 1.6; }
.editorial-link:hover .editorial-card h3,
.editorial-link:focus-visible .editorial-card h3 { text-decoration: underline; text-underline-offset: 2px; }
.read-more { font-size: .8125rem; font-weight: 600; color: var(--accent); margin-top: .25rem; }

/* ─── Newsletter ─────────────────────────────────────────────────── */
.newsletter-section {
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  color: #fff; padding-block: 4.5rem;
}
.newsletter-inner {
  display: grid; grid-template-columns: 1fr 1.2fr;
  gap: 3rem; align-items: center;
}
.newsletter-copy h2 {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800; letter-spacing: -.02em; margin-bottom: .6rem;
}
.newsletter-copy p { color: rgba(255,255,255,.7); font-size: 1rem; }
.newsletter-form { display: flex; flex-direction: column; gap: .75rem; }
.newsletter-field { display: flex; flex-direction: column; gap: .45rem; }
.newsletter-field label { font-size: .875rem; font-weight: 600; }
.newsletter-input-row { display: flex; gap: .5rem; flex-wrap: wrap; }
.newsletter-input-row input[type="email"] {
  flex: 1; min-width: 180px;
  padding: .72rem 1rem;
  background: rgba(255,255,255,.1);
  border: 1.5px solid rgba(255,255,255,.25);
  border-radius: var(--r-sm);
  color: #fff; font-size: .9375rem;
  font-family: inherit;
}
.newsletter-input-row input[type="email"]::placeholder { color: rgba(255,255,255,.45); }
.newsletter-input-row input[type="email"]:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 0;
  border-color: #fff;
}
.field-hint { font-size: .78rem; color: rgba(255,255,255,.55); }
.form-status {
  font-size: .9rem; font-weight: 600; min-height: 1.4em;
  color: #86efac; /* green-300, good contrast on dark bg */
}

/* ─── Footer ─────────────────────────────────────────────────────── */
.site-footer {
  background: var(--text); color: rgba(255,255,255,.75);
  padding-top: 3.5rem; padding-bottom: 2rem;
}
.footer-inner {
  display: grid;
  grid-template-columns: 1.8fr 1fr 1fr 1fr;
  gap: 2.5rem; margin-bottom: 3rem;
}
.footer-logo { color: #fff; }
.footer-tagline { font-size: .85rem; color: rgba(255,255,255,.55); margin-top: .5rem; max-width: 28ch; line-height: 1.6; }
.social-links {
  display: flex; gap: .6rem; margin-top: 1.25rem;
}
.social-links a {
  display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: var(--r-sm);
  color: rgba(255,255,255,.65); text-decoration: none;
  transition: background .15s, color .15s;
}
.social-links a:hover { background: rgba(255,255,255,.1); color: #fff; }

/* Footer nav columns */
.footer-col h3 {
  font-size: .72rem; font-weight: 700; letter-spacing: .1em;
  text-transform: uppercase; color: rgba(255,255,255,.45);
  margin-bottom: .9rem;
}
.footer-col ul { display: flex; flex-direction: column; gap: .45rem; }
.footer-col a {
  font-size: .875rem; text-decoration: none;
  color: rgba(255,255,255,.7);
}
.footer-col a:hover { color: #fff; text-decoration: underline; }

/* Footer bottom */
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,.1);
  padding-top: 1.5rem;
  display: flex; align-items: center;
  justify-content: space-between;
  flex-wrap: wrap; gap: 1rem;
}
.copyright { font-size: .8rem; color: rgba(255,255,255,.4); }
.legal-links {
  display: flex; gap: 1.5rem; flex-wrap: wrap;
}
.legal-links a { font-size: .8rem; color: rgba(255,255,255,.45); text-decoration: none; }
.legal-links a:hover { color: rgba(255,255,255,.8); text-decoration: underline; }

/* ─── Cart notification ──────────────────────────────────────────── */
.cart-notification {
  position: fixed; bottom: 1.5rem; right: 1.5rem;
  background: var(--text); color: #fff;
  padding: .9rem 1.25rem; border-radius: var(--r-md);
  font-size: .9rem; font-weight: 600;
  box-shadow: var(--shadow-lg);
  max-width: 320px;
  transform: translateY(120%); opacity: 0;
  transition: transform .3s ease, opacity .3s ease;
  pointer-events: none; z-index: 500;
}
@media (prefers-reduced-motion: reduce) {
  .cart-notification { transition: none; }
}
.cart-notification.is-visible {
  transform: translateY(0); opacity: 1;
}

/* ─── Responsive ─────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-card--wide { grid-column: span 2; grid-row: auto; }
  .deal-card--wide .deal-image { aspect-ratio: 16/7; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card--hero { grid-column: span 2; }
  .trust-list { grid-template-columns: repeat(2, 1fr); }
  .footer-inner { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
}

@media (max-width: 768px) {
  .hero { grid-template-columns: 1fr; }
  .hero-image { display: none; }
  .hero-content {
    padding: 3.5rem 0; max-width: 100%;
    padding-inline: 1.5rem;
  }
  .newsletter-inner { grid-template-columns: 1fr; gap: 2rem; }
  .footer-inner { grid-template-columns: 1fr 1fr; gap: 2rem; }
  .footer-brand { grid-column: span 2; }
  nav[aria-label="Primary"] { display: none; }
  nav[aria-label="Primary"].is-open {
    display: block;
    position: absolute; top: 64px; left: 0; right: 0;
    background: var(--bg);
    border-bottom: 1px solid var(--border);
    padding: 1rem 1.5rem; z-index: 99;
  }
  nav[aria-label="Primary"].is-open .nav-list {
    flex-direction: column; align-items: flex-start;
  }
  .mobile-menu-btn { display: inline-flex; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card--wide { grid-column: auto; }
}

@media (max-width: 560px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card--hero { grid-column: auto; }
  .trust-list { grid-template-columns: 1fr 1fr; }
  .footer-inner { grid-template-columns: 1fr; }
  .footer-brand { grid-column: auto; }
}

@media (max-width: 320px) {
  .container { padding-inline: 1rem; }
  .hero-content h1 { font-size: 1.9rem; }
  .product-grid { grid-template-columns: 1fr; }
}

/* ─── Forced colors ──────────────────────────────────────────────── */
@media (forced-colors: active) {
  .product-card, .deal-card, .editorial-card {
    border: 1px solid ButtonText;
  }
  .btn-primary, .btn-add-cart {
    forced-color-adjust: none;
    background: ButtonText; color: ButtonFace;
    border-color: ButtonText;
  }
  .promo-banner {
    forced-color-adjust: none;
    background: Highlight; color: HighlightText;
  }
  .badge, .deal-tag, .discount-badge {
    forced-color-adjust: none;
    background: Mark; color: MarkText;
    border: 1px solid ButtonText;
  }
  .cart-notification {
    forced-color-adjust: none;
    background: Canvas; color: CanvasText;
    border: 2px solid ButtonText;
  }
}

/* ─── Reduced motion ─────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .01ms !important;
    transition-duration: .01ms !important;
  }
}

/* ─── Color scheme ───────────────────────────────────────────────── */
@media (prefers-color-scheme: dark) {
  :root {
    --bg:         #0f172a;
    --surface:    #1e293b;
    --surface-2:  #334155;
    --border:     #334155;
    --text:       #f8fafc;
    --text-muted: #94a3b8;
    --accent-light: #431407;
    --shadow:     0 1px 8px rgba(0,0,0,.4);
    --shadow-lg:  0 6px 24px rgba(0,0,0,.5);
  }
  .site-header   { background: #0f172a; }
  .logo          { color: var(--accent); }
  .submenu       { background: #1e293b; }
  .skip-link     { background: var(--text); color: var(--bg); }
  .product-image-wrap { background: var(--surface); }
  .wishlist-btn  { background: rgba(15,23,42,.85); border-color: var(--border); }
  .newsletter-input-row input[type="email"] { color: var(--text); }
  .cart-notification { background: var(--surface); color: var(--text); border: 1px solid var(--border); }
}
