        }
      }

      showCartNotification(name);
    });
  });

  /* ── Newsletter form ──────────────────────────────────────────── */
  var newsletterForm = document.querySelector('.newsletter-form');
  if (newsletterForm) {
    newsletterForm.addEventListener('submit', function (e) {
      e.preventDefault();
      var input  = this.querySelector('#email-input');
      var status = this.querySelector('.form-status');
      if (!input || !status) return;

      if (!input.value.trim() || !input.validity.valid) {
        status.textContent = 'Please enter a valid email address.';
        status.style.color = '#fca5a5'; // red-300, readable on dark
        input.focus();
        return;
      }

      status.style.color = '#86efac'; // green-300
      status.textContent = 'You\u2019re subscribed! Check your inbox for a welcome email.';
      this.reset();
    });
  }

})();
